                <iframe src="https://www.google.com/maps/embedded/map?center=your%20city&zoom=12" style="border: 1px solid #333;"></iframe>
            </div>
        </div>
    </div>

    <script>
        // Simple countdown timer
        setInterval(function() {
            document.querySelector('.timer').innerHTML = new Date().toLocaleString();
        }, 1000);

